function windSymbols(cells){const lines=[],heads=[];for(let k=0;k<cells.length;k+=3){const c=cells[k],speed=Math.hypot(c.wind.u,c.wind.v);if(speed<.05)continue;const bearing=CPS.wrap(Math.atan2(c.wind.u,c.wind.v)*180/Math.PI),length=.07+Math.min(speed,25)*.004;const a=turf.destination(c.center,length/2,bearing+180).geometry.coordinates,b=turf.destination(c.center,length/2,bearing).geometry.coordinates;const pr={speed:Math.round(speed*36)/10,from:Math.round(CPS.wrap(bearing+180)),toward:Math.round(bearing),kind:'wind'};lines.push(turf.lineString([a,b],pr));const h1=turf.destination(b,length*.28,bearing+150).geometry.coordinates,h2=turf.destination(b,length*.28,bearing-150).geometry.coordinates;heads.push(turf.lineString([h1,b,h2],pr));}return fc([...lines,...heads]);}
