$('windMode').onchange=()=>{windControls();changed();};$('loadForecast').onclick=()=>{forecast=null;changed();};
$('stationChoice').onchange=changed;$('stationTime').onclick=()=>{const s=stationList.find(s=>s.id===$('stationChoice').value),r=s?.rows.at(-1);if(!r){status('Sem observação de vento nesta estação.');return;}const d=new Date(r.time),hour=Math.ceil((d.getUTCHours()*60+d.getUTCMinutes())/30)/2;d.setUTCHours(0,0,0,0);d.setUTCMinutes(hour*60);$('day').value=d.toISOString().slice(0,10);$('hour').value=d.getUTCHours()+d.getUTCMinutes()/60;changed();};
$('windFile').onchange=async()=>{const file=$('windFile').files[0];if(!file)return;try{if(file.size>8e6)throw new Error('Máximo 8 MB.');const data=JSON.parse(await file.text());if(data.type!=='FeatureCollection'||!Array.isArray(data.features)||!data.features.length||data.features.length>10000)throw new Error('FeatureCollection com 1–10 000 pontos necessária.');if(typeof data.wind_source!=='string'||!data.wind_source.trim()||!Number.isFinite(data.height_m)||data.height_m<=0||typeof data.valid_time!=='string'||!/(Z|[+-]\d\d:\d\d)$/.test(data.valid_time)||!Number.isFinite(Date.parse(data.valid_time)))throw new Error('Indique wind_source, height_m > 0 e valid_time ISO com fuso no topo do GeoJSON.');for(const p of data.features){const c=p.geometry?.coordinates;if(p.geometry?.type!=='Point'||!Array.isArray(c)||!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>75||!Number.isFinite(p.properties?.u)||!Number.isFinite(p.properties?.v)||Math.hypot(p.properties.u,p.properties.v)>100)throw new Error('Pontos WGS84 e propriedades u/v numéricas em m/s (≤100 m/s) necessárias.');}windPoints=data.features;windMeta={source:data.wind_source,valid_time:data.valid_time,height_m:data.height_m,filename:file.name,interpolation:'nearest <=1 km',verified:false};windFieldMeta=windMeta;$('windMode').value='field';windControls();$('direction').disabled=true;$('speed').disabled=true;$('windSource').textContent=`Campo importado · ${data.features.length} vetores · ${data.height_m} m · válido ${data.valid_time}. Hora solar independente; o vento mantém esta validade.`;changed();}catch(e){status(`Importação recusada: ${e.message}`);$('windFile').value='';}};
function exportScenario(){if(!result)return null;const mtg=CPSMTG.windowAt(mtgCollection,new Date(result.metadata.valid_time));const features=[{...result.metadata.origin,properties:{kind:'origin'}},...result.polys.features.map(f=>({...f,properties:{...f.properties,kind:'potential_polygon'}})),...result.displayPolys.features.map(f=>({...f,properties:{...f.properties,kind:'potential_polygon_display'}})),...result.edges.features,...result.wind.features,...result.prop.features,...mtg.features];return {...fc(features),metadata:{...result.metadata,solver_ready:false,requires_review:['experimental_CPS_rules','no_fuel_or_barrier_model','approximate_propagation','regional_or_uniform_wind_unless_imported_field'],mtg:{source_available:mtgAvailable,latest_observation:mtgCollection.latest_observation||null,window_minutes:60,detections_in_window:mtg.features.length,used_to_modify_model:false}}};}
$('export').onclick=()=>{const scenario=exportScenario();if(!scenario)return;const blob=new Blob([JSON.stringify(scenario,null,2)],{type:'application/geo+json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`firepotential-${result.metadata.valid_time.replaceAll(':','-')}.geojson`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
async function openSavedJob(id){try{const d=await CPSNinja.getSaved(id);if(d.metadata.propagation_executed)throw Error('Este resultado pertence a um ensaio de propagação. Abra um resultado de alinhamentos FirePotential.');invalidate();origin=turf.feature(d.metadata.origin);exactLaunchTime=d.field.valid_time;$('day').value=exactLaunchTime.slice(0,10);const t=new Date(exactLaunchTime);$('hour').value=t.getUTCHours()+t.getUTCMinutes()/60;$('cloudHours').value=d.wind_fields?.length||1;windMeta={source:d.field.wind_source,product:'local_terrain_wind',valid_time:d.field.valid_time,height_m:d.field.height_m,cloud_job_id:d.job_id,verified:true};updateOrigin();renderCloud(d,origin);const b=turf.bbox(fc(d.polygons.features));map.fitBounds([[b[0],b[1]],[b[2],b[3]]],{padding:65});}catch(e){status(e.message);}}
$('openSaved').onclick=()=>openSavedJob($('savedJob').value);
function stopCloudPlayback(){if(cloudPlayback)clearInterval(cloudPlayback);cloudPlayback=null;$('playHours').textContent='Reproduzir horas ▶';}
$('playHours').onclick=()=>{if(cloudPlayback){stopCloudPlayback();return;}const d=CPSNinja.getResult();if(!d||d.wind_fields.length<2)return;$('playHours').textContent='Pausar horas ❚❚';cloudPlayback=setInterval(()=>{if(document.hidden)return;const next=(+$('cloudEpoch').value+1)%d.wind_fields.length;labelMarkers.forEach(m=>m.remove());labelMarkers=[];renderCloud(d,origin,next);},3000);};
$('cloudEpoch').onchange=()=>{stopCloudPlayback();const d=CPSNinja.getResult();if(!d)return;labelMarkers.forEach(m=>m.remove());labelMarkers=[];renderCloud(d,origin,+$('cloudEpoch').value);};
CPSNinja.initialize();
window.FirePotential3D={schemaVersion:'firepotential/1.0',getScenario:()=>{const s=exportScenario();return s?JSON.parse(JSON.stringify(s)):null;}};
$('mtgFile').onchange=async()=>{try{const file=$('mtgFile').files[0];if(!file)return;if(file.size>15e6)throw Error('Máximo 15 MB.');mtgCollection=CPSMTG.normalize(JSON.parse(await file.text()));mtgAvailable=true;updateMTG();}catch(e){$('mtgInfo').textContent=`Importação MTG recusada: ${e.message}`;}};
$('mtgWMS').onchange=()=>{if(ready&&map.getLayer('mtg-wms-layer'))map.setLayoutProperty('mtg-wms-layer','visibility',$('mtgWMS').checked?'visible':'none');};
setInterval(()=>{if(!document.hidden){ensureStations(true).catch(()=>{});loadMTG();loadMTGWMS();}},300000);
window.addEventListener('error',e=>{status(`Erro da aplicação: ${e.message}. Verifique acesso à Internet e recarregue.`);});
window.addEventListener('unhandledrejection',e=>{status(`Falha ao carregar: ${e.reason?.message||e.reason}. Verifique acesso à Internet.`);});
